import { Semaphore } from 'async-mutex';
import BigNumber from 'bignumber.js';

import {
  backgroundClass,
  backgroundMethod,
} from '@onekeyhq/shared/src/background/backgroundDecorators';
import { getNetworkIdsMap } from '@onekeyhq/shared/src/config/networkIds';
import { IMPL_EVM } from '@onekeyhq/shared/src/engine/engineConsts';
import { OneKeyError } from '@onekeyhq/shared/src/errors';
import {
  EAppEventBusNames,
  appEventBus,
} from '@onekeyhq/shared/src/eventBus/appEventBus';
import { defaultLogger } from '@onekeyhq/shared/src/logger/logger';
import accountUtils from '@onekeyhq/shared/src/utils/accountUtils';
import timerUtils from '@onekeyhq/shared/src/utils/timerUtils';
import { ENetworkStatus, type IServerNetwork } from '@onekeyhq/shared/types';
import type { IChainListItem } from '@onekeyhq/shared/types/customNetwork';
import type {
  ICustomRpcItem,
  IDBCustomRpc,
  IMeasureRpcStatusParams,
} from '@onekeyhq/shared/types/customRpc';
import { EServiceEndpointEnum } from '@onekeyhq/shared/types/endpoint';
import type { IToken } from '@onekeyhq/shared/types/token';

import { type IDBCloudSyncItem } from '../dbs/local/types';
import { vaultFactory } from '../vaults/factory';

import ServiceBase from './ServiceBase';

@backgroundClass()
class ServiceCustomRpc extends ServiceBase {
  private semaphore = new Semaphore(1);

  private buildChainListRequestParams(params: {
    keywords?: string;
    page?: number;
  }): { keywords?: string; page: number; showTestNet: boolean } {
    const keywords = params.keywords?.trim() || undefined;
    const page = Math.max(1, Math.floor(params.page ?? 1));
    return {
      keywords,
      page,
      showTestNet: true,
    };
  }

  private async fetchChainListPage(page: number): Promise<IChainListItem[]> {
    const client = await this.getClient(EServiceEndpointEnum.Wallet);
    const resp = await client.get<{ data: IChainListItem[] }>(
      '/wallet/v1/network/chainlist',
      { params: this.buildChainListRequestParams({ page }) },
    );
    return resp.data.data || [];
  }

  constructor({ backgroundApi }: { backgroundApi: any }) {
    super({ backgroundApi });
  }

  async buildCustomRpcSyncItems({
    customRpcItems,
    isDeleted,
  }: {
    customRpcItems: IDBCustomRpc[];
    isDeleted: boolean;
  }) {
    const syncManagers = this.backgroundApi.servicePrimeCloudSync.syncManagers;
    const syncCredential =
      await this.backgroundApi.servicePrimeCloudSync.getSyncCredentialSafe();

    const syncItems = (
      await Promise.all(
        customRpcItems.map(async (customRpc) => {
          return syncManagers.customRpc.buildSyncItemByDBQuery({
            syncCredential,
            dbRecord: customRpc,
            dataTime: undefined,
            isDeleted,
          });
        }),
      )
    ).filter(Boolean);
    return syncItems;
  }

  async buildCustomNetworkSyncItems({
    customNetworks,
    isDeleted,
  }: {
    customNetworks: IServerNetwork[];
    isDeleted: boolean;
  }) {
    const syncManagers = this.backgroundApi.servicePrimeCloudSync.syncManagers;
    const syncCredential =
      await this.backgroundApi.servicePrimeCloudSync.getSyncCredentialSafe();

    const syncItems = (
      await Promise.all(
        customNetworks.map(async (customNetwork) => {
          return syncManagers.customNetwork.buildSyncItemByDBQuery({
            syncCredential,
            dbRecord: customNetwork,
            dataTime: undefined,
            isDeleted,
          });
        }),
      )
    ).filter(Boolean);
    return syncItems;
  }

  // TODO move to CloudSyncFlowManagerBase
  async withCustomRpcCloudSync({
    fn,
    customRpcItems,
    isDeleted,
    skipSaveLocalSyncItem,
  }: // skipEventEmit,
  {
    fn: () => Promise<void>;
    customRpcItems: IDBCustomRpc[];
    isDeleted: boolean;
    skipSaveLocalSyncItem?: boolean;
    skipEventEmit?: boolean;
  }) {
    let syncItems: IDBCloudSyncItem[] = [];
    if (!skipSaveLocalSyncItem) {
      syncItems = await this.buildCustomRpcSyncItems({
        customRpcItems,
        isDeleted,
      });
    }
    await this.backgroundApi.localDb.addAndUpdateFreshSyncItems({
      items: syncItems,
      fn,
    });
  }

  async withCustomNetworkCloudSync({
    fn,
    customNetworks,
    isDeleted,
    skipSaveLocalSyncItem,
  }: // skipEventEmit,
  {
    fn: () => Promise<void>;
    customNetworks: IServerNetwork[];
    isDeleted: boolean;
    skipSaveLocalSyncItem?: boolean;
    skipEventEmit?: boolean;
  }) {
    let syncItems: IDBCloudSyncItem[] = [];
    if (!skipSaveLocalSyncItem) {
      syncItems = await this.buildCustomNetworkSyncItems({
        customNetworks,
        isDeleted,
      });
    }
    await this.backgroundApi.localDb.addAndUpdateFreshSyncItems({
      items: syncItems,
      fn,
    });
  }

  /*= ===============================
   *       Custom RPC
   *============================== */

  @backgroundMethod()
  public async addCustomRpc({
    customRpc,
    skipSaveLocalSyncItem,
    skipEventEmit,
  }: {
    customRpc: IDBCustomRpc;
    skipSaveLocalSyncItem?: boolean;
    skipEventEmit?: boolean;
  }) {
    return this.withCustomRpcCloudSync({
      fn: () =>
        this.backgroundApi.simpleDb.customRpc.addCustomRpc({
          rpcInfo: customRpc,
        }),
      customRpcItems: [customRpc],
      isDeleted: false,
      skipSaveLocalSyncItem,
      skipEventEmit,
    });
  }

  @backgroundMethod()
  public async deleteCustomRpc({
    customRpc,
    skipSaveLocalSyncItem,
    skipEventEmit,
  }: {
    customRpc: IDBCustomRpc;
    skipSaveLocalSyncItem?: boolean;
    skipEventEmit?: boolean;
  }) {
    return this.withCustomRpcCloudSync({
      fn: () =>
        this.backgroundApi.simpleDb.customRpc.deleteCustomRpc(
          customRpc.networkId,
        ),
      customRpcItems: [customRpc],
      isDeleted: true,
      skipSaveLocalSyncItem,
      skipEventEmit,
    });
  }

  @backgroundMethod()
  public async updateCustomRpcEnabledStatus(params: {
    networkId: string;
    enabled: boolean;
    skipSaveLocalSyncItem?: boolean;
    skipEventEmit?: boolean;
  }) {
    const { networkId, enabled, skipSaveLocalSyncItem, skipEventEmit } = params;
    const customRpc = await this.getCustomRpcForNetwork(networkId);
    if (!customRpc) {
      return;
    }
    return this.withCustomRpcCloudSync({
      fn: () =>
        this.backgroundApi.simpleDb.customRpc.updateCustomRpcEnabledStatus(
          params,
        ),
      customRpcItems: [{ ...customRpc, enabled }],
      isDeleted: false,
      skipSaveLocalSyncItem,
      skipEventEmit,
    });
  }

  @backgroundMethod()
  public async getAllCustomRpc(): Promise<ICustomRpcItem[]> {
    const result =
      await this.backgroundApi.simpleDb.customRpc.getAllCustomRpc();
    const itemsWithNetwork = (
      await Promise.all(
        result.map(async (r) => {
          const network =
            await this.backgroundApi.serviceNetwork.getNetworkSafe({
              networkId: r.networkId,
            });
          if (!network) {
            return null;
          }
          return {
            ...r,
            network,
          };
        }),
      )
    ).filter(Boolean);
    return itemsWithNetwork.toSorted((a, b) =>
      (a.network?.name ?? '').localeCompare(b.network?.name ?? ''),
    );
  }

  @backgroundMethod()
  public async getCustomRpcForNetwork(networkId: string) {
    return this.backgroundApi.simpleDb.customRpc.getCustomRpcForNetwork(
      networkId,
    );
  }

  @backgroundMethod()
  public async measureRpcStatus(
    params: IMeasureRpcStatusParams & { networkId: string },
  ) {
    const vault = await vaultFactory.getChainOnlyVault({
      networkId: params.networkId,
    });
    const result = await vault.getCustomRpcEndpointStatus({
      rpcUrl: params.rpcUrl,
      validateChainId: params.validateChainId,
    });
    return result;
  }

  /*= ===============================
   *       Custom Network
   *============================== */
  @backgroundMethod()
  public async getChainIdByRpcUrl(params: { rpcUrl: string }) {
    const vault = await vaultFactory.getChainOnlyVault({
      networkId: getNetworkIdsMap().eth,
    });
    const result = await vault.getCustomRpcEndpointStatus({
      rpcUrl: params.rpcUrl,
      validateChainId: false,
    });
    return {
      chainId: result.chainId,
    };
  }

  @backgroundMethod()
  public async measureCustomNetworkRpcStatus(params: {
    rpcUrl: string;
    chainId: number;
  }) {
    const vault = await vaultFactory.getChainOnlyVault({
      networkId: getNetworkIdsMap().eth,
    });
    const result = await vault.getCustomRpcEndpointStatus({
      rpcUrl: params.rpcUrl,
      validateChainId: false,
    });
    if (
      !new BigNumber(result.chainId ?? 0).isEqualTo(
        new BigNumber(params.chainId),
      )
    ) {
      throw new OneKeyError('Invalid chainId');
    }
    return result;
  }

  async upsertCustomNetworkInfo({
    networkInfo,
    rpcUrl,
    skipSaveLocalSyncItem,
    skipEventEmit,
  }: {
    networkInfo: IServerNetwork;
    rpcUrl: string;
    skipSaveLocalSyncItem?: boolean;
    skipEventEmit?: boolean;
  }) {
    const networkId = networkInfo.id;

    // Insert custom rpc
    await this.addCustomRpc({
      customRpc: {
        networkId,
        enabled: true,
        rpc: rpcUrl,
        isCustomNetwork: true,
        updatedAt: undefined,
      },
      skipSaveLocalSyncItem,
      skipEventEmit,
    });

    await this.withCustomNetworkCloudSync({
      fn: async () => {
        // Insert native token
        const nativeToken: IToken = {
          decimals: 18,
          name: networkInfo.symbol,
          symbol: networkInfo.symbol,
          address: '', // native token always be empty
          logoURI: '',
          isNative: true,
        };
        await this.backgroundApi.simpleDb.localTokens.updateTokens({
          networkId,
          tokens: [nativeToken],
        });
        // Insert custom network
        await this.backgroundApi.simpleDb.customNetwork.upsertCustomNetwork({
          networkInfo,
        });

        void this.backgroundApi.serviceNetwork.clearAllNetworksCache();
        setTimeout(() => {
          void this.backgroundApi.serviceNetwork.clearNetworkVaultSettingsCache();
          if (!skipEventEmit) {
            appEventBus.emit(EAppEventBusNames.AddedCustomNetwork, undefined);
          }
        }, 500);
      },
      customNetworks: [networkInfo],
      isDeleted: false,
      skipSaveLocalSyncItem,
      skipEventEmit,
    });
  }

  @backgroundMethod()
  public async upsertCustomNetwork(params: {
    networkName: string;
    rpcUrl: string;
    chainId: number;
    symbol: string;
    blockExplorerUrl: string;
  }) {
    const vault = await vaultFactory.getChainOnlyVault({
      networkId: getNetworkIdsMap().eth,
    });
    const { isEIP1559FeeEnabled } = await vault.checkFeeSupportInfo({
      rpcUrl: params.rpcUrl,
    });

    const { chainId } = params;
    const networkId = accountUtils.buildCustomEvmNetworkId({
      chainId: chainId.toString(),
    });

    const networkInfo: IServerNetwork = {
      impl: IMPL_EVM,
      chainId: chainId.toString(),
      id: networkId,
      name: params.networkName,
      symbol: params.symbol,
      code: params.networkName,
      shortcode: params.networkName,
      shortname: params.networkName,
      decimals: 18,
      feeMeta: {
        decimals: 9,
        symbol: 'Gwei',
        isEIP1559FeeEnabled,
        // TODO: check isWithL1BaseFee
        isWithL1BaseFee: false,
      },
      status: ENetworkStatus.LISTED,
      isTestnet: false,
      logoURI: '',
      defaultEnabled: true,
      backendIndex: false,
      explorerURL: params.blockExplorerUrl,
      isCustomNetwork: true,
    };

    return this.upsertCustomNetworkInfo({
      networkInfo,
      rpcUrl: params.rpcUrl,
    });
  }

  @backgroundMethod()
  public async deleteCustomNetwork(params: {
    networkId: string;
    replaceByServerNetwork?: boolean;
    skipSaveLocalSyncItem?: boolean;
    skipEventEmit?: boolean;
  }) {
    const { skipEventEmit, skipSaveLocalSyncItem } = params;
    if (params.replaceByServerNetwork) {
      await this.updateCustomRpcEnabledStatus({
        networkId: params.networkId,
        enabled: false,
        skipEventEmit,
        skipSaveLocalSyncItem,
      });
    } else {
      const customRpc = await this.getCustomRpcForNetwork(params.networkId);
      if (customRpc) {
        await this.deleteCustomRpc({
          customRpc,
          skipEventEmit,
          skipSaveLocalSyncItem,
        });
      }
    }

    const allCustomNetwork = await this.getAllCustomNetworks();
    const customNetwork = allCustomNetwork.find(
      (n) => n.id === params.networkId,
    );
    if (customNetwork) {
      await this.withCustomNetworkCloudSync({
        fn: async () => {
          await this.backgroundApi.simpleDb.customNetwork.deleteCustomNetwork(
            params,
          );
          void this.backgroundApi.serviceNetwork.clearAllNetworksCache();
          setTimeout(() => {
            if (!skipEventEmit) {
              appEventBus.emit(EAppEventBusNames.AddedCustomNetwork, undefined);
            }
          }, 300);
        },
        customNetworks: [customNetwork],
        isDeleted: true,
        skipSaveLocalSyncItem,
        skipEventEmit,
      });
    }
  }

  @backgroundMethod()
  public async getAllCustomNetworks(): Promise<IServerNetwork[]> {
    try {
      return await this.backgroundApi.simpleDb.customNetwork.getAllCustomNetworks();
    } catch {
      return [];
    }
  }

  /*= ===============================
   *       Server Network
   *============================== */
  @backgroundMethod()
  public async getServerNetworks(): Promise<IServerNetwork[]> {
    return this.semaphore.runExclusive(async () => {
      try {
        const { networks, lastFetchTime } =
          await this.backgroundApi.simpleDb.serverNetwork.getAllServerNetworks();
        const now = Date.now();

        if (
          !lastFetchTime ||
          now - lastFetchTime >= timerUtils.getTimeDurationMs({ hour: 1 })
        ) {
          void this.fetchNetworkFromServer().catch((error) => {
            defaultLogger.account.wallet.getServerNetworksError(error);
          });
        }
        defaultLogger.account.wallet.getServerNetworks(networks);
        return networks || [];
      } catch (error) {
        defaultLogger.account.wallet.getServerNetworksError(error);
        return [];
      }
    });
  }

  // Resolves once the server-network cache has been filled at least once.
  // Callers that gate on server-delivered networks (e.g. wallet-config
  // aggregate members) use this instead of getServerNetworks, which returns
  // the possibly empty cache and only refreshes it in the background.
  // Fetch failures are swallowed: the caller proceeds with the cache it has
  // and the hourly refresh in getServerNetworks retries later.
  @backgroundMethod()
  public async ensureServerNetworksFetched(): Promise<void> {
    try {
      const { lastFetchTime } =
        await this.backgroundApi.simpleDb.serverNetwork.getAllServerNetworks();
      if (lastFetchTime) {
        return;
      }
      await this.fetchNetworkFromServer();
    } catch (error) {
      defaultLogger.account.wallet.getServerNetworksError(error);
    }
  }

  // Whether the server-network cache has been filled at least once. Unlike
  // getServerNetworks, which swallows storage errors and returns an empty
  // list, a read failure propagates here so callers gating on the registry
  // can tell "unavailable" apart from "empty" and fail open.
  @backgroundMethod()
  public async isServerNetworkRegistryFilled(): Promise<boolean> {
    const { lastFetchTime } =
      await this.backgroundApi.simpleDb.serverNetwork.getAllServerNetworks();
    return !!lastFetchTime;
  }

  private _fetchNetworkFromServerPromise: Promise<IServerNetwork[]> | undefined;

  // Single-flight: getServerNetworks fires a background refresh from every
  // stale read, so concurrent callers share one in-flight request instead of
  // each issuing their own.
  @backgroundMethod()
  public async fetchNetworkFromServer(): Promise<IServerNetwork[]> {
    if (this._fetchNetworkFromServerPromise) {
      return this._fetchNetworkFromServerPromise;
    }
    this._fetchNetworkFromServerPromise =
      this._fetchNetworkFromServer().finally(() => {
        this._fetchNetworkFromServerPromise = undefined;
      });
    return this._fetchNetworkFromServerPromise;
  }

  private async _fetchNetworkFromServer(): Promise<IServerNetwork[]> {
    // await timerUtils.wait(3000 * 10);
    defaultLogger.account.wallet.fetchNetworkFromServer();
    // Request /wallet/v1/network/list to get all evm networks
    const client = await this.getClient(EServiceEndpointEnum.Wallet);
    const resp = await client.get<{ data: IServerNetwork[] }>(
      '/wallet/v1/network/list',
      {
        params: {
          onlyEvmNetworks: true,
        },
      },
    );

    const serverNetworks = resp.data.data;
    const presetNetworkIds = Object.values(getNetworkIdsMap());
    // Persist ALL non-preset server networks, INCLUDING delisted (TRASH) ones,
    // keeping their `status`. The backend marks a network as delisted by flipping
    // its `status` to TRASH while still returning the entry (it does NOT drop it from
    // the list). If we filtered TRASH out here, a network that was cached while
    // LISTED and later delisted would keep its stale LISTED snapshot in the DB
    // forever. Instead we store the real status and let the read/merge layer
    // (ServiceNetwork.getAllNetworks) filter TRASH out.
    const usedNetworks = serverNetworks.filter(
      (n) => !presetNetworkIds.includes(n.id),
    );

    // Snapshot the previous server-network set so the refresh event below is only
    // fanned out when the set actually changed (id added/removed or status
    // flipped), instead of on every hourly fetch.
    const { networks: prevServerNetworks } =
      await this.backgroundApi.simpleDb.serverNetwork.getAllServerNetworks();
    const serverNetworkSignature = (list: IServerNetwork[]) =>
      list
        .map((n) => `${n.id}:${n.status}`)
        .toSorted()
        .join(',');
    const serverNetworkListChanged =
      serverNetworkSignature(prevServerNetworks ?? []) !==
      serverNetworkSignature(usedNetworks);

    await this.backgroundApi.simpleDb.serverNetwork.upsertServerNetworks({
      networkInfos: usedNetworks,
    });

    // delete custom networks
    const customNetworks = await this.getAllCustomNetworks();
    for (const customNetwork of customNetworks) {
      if (serverNetworks.find((n) => n.id === customNetwork.id)) {
        await this.deleteCustomNetwork({
          networkId: customNetwork.id,
          replaceByServerNetwork: true,
        });
      }
    }

    // If the server network is updated, clear the getAllNetworks cache
    await this.backgroundApi.serviceNetwork.clearAllNetworksCache();

    // Notify network-list views to refresh in place, but only when the set
    // actually changed. A delisted (TRASH) network is dropped by the read/merge
    // layer only AFTER this fetch persists its new status, so without this signal
    // an already-rendered selector keeps showing the stale entry until reopened.
    // We reuse AddedCustomNetwork, the de-facto "network list changed, refresh"
    // signal every network selector already listens to.
    if (serverNetworkListChanged) {
      appEventBus.emit(EAppEventBusNames.AddedCustomNetwork, undefined);
      // The cached aggregate-token maps were gated on the previous
      // server-network set, so let the next syncWalletConfigIfNeeded rebuild
      // them instead of waiting for the config TTL.
      await this.backgroundApi.simpleDb.aggregateToken.clearConfigSyncMeta();
    }

    defaultLogger.account.wallet.insertServerNetwork(usedNetworks);
    return usedNetworks;
  }

  @backgroundMethod()
  async searchChainListByKeywords(params: {
    keywords?: string;
    page?: number;
  }): Promise<IChainListItem[]> {
    const requestParams = this.buildChainListRequestParams(params);
    if (requestParams.keywords) {
      const client = await this.getClient(EServiceEndpointEnum.Wallet);
      const resp = await client.get<{ data: IChainListItem[] }>(
        '/wallet/v1/network/chainlist',
        { params: requestParams },
      );
      return resp.data.data || [];
    }

    return this.fetchChainListPage(requestParams.page);
  }

  @backgroundMethod()
  async searchCustomNetworkByChainList(params: { chainId: string }) {
    try {
      const chainId = new BigNumber(params.chainId).toNumber();
      const client = await this.getClient(EServiceEndpointEnum.Wallet);
      const resp = await client.get<{ data: IChainListItem[] }>(
        '/wallet/v1/network/chainlist',
        {
          params: this.buildChainListRequestParams({
            keywords: String(chainId),
            page: 1,
          }),
        },
      );
      return (
        resp.data.data.find((n) =>
          new BigNumber(n.chainId).isEqualTo(new BigNumber(chainId)),
        ) || null
      );
    } catch {
      return null;
    }
  }
}

export default ServiceCustomRpc;
